"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def action_deltas(env, actions: Sequence[int] = ACTIONS) -> Dict[int, dict]:
    base = arr(env.frame()).copy()
    out = {}
    for action in actions:
        clone = env.clone()
        clone.step(action)
        out[int(action)] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence[int]):
    clone = env.clone()
    for action in actions:
        if clone.terminal():
            break
        clone.step(int(action))
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }


def changed_signature(env, actions: Sequence[int], cell: int = 4):
    before = block_signatures(env.frame(), cell)
    clone = replay(env, actions)
    after = block_signatures(clone.frame(), cell)
    return {k: (before.get(k), after.get(k)) for k in sorted(set(before) | set(after))
            if before.get(k) != after.get(k)}


def bounded_bfs(env, goal_fn, actions: Sequence[int] = (UP, DOWN, LEFT, RIGHT, USE),
                key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Generic clone BFS over observational keys. Use small max_states first."""
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()
    start_key = key_fn(env)
    q = deque([(env.clone(), [])])
    seen = {start_key}
    while q and len(seen) <= max_states:
        node, path = q.popleft()
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth:
            continue
        for action in actions:
            child = node.clone()
            child.step(int(action))
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            q.append((child, path + [int(action)]))
    return None


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(int(action))
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        for action in action_fn(node):
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

def _solid_playfield_squares(
    env, colors=None, excluded_colors=(), min_area=1
):
    return [
        blob for blob in connected_components(
            env.frame(), colors=colors, min_area=min_area
        )
        if (
            blob.bbox[0] >= 10
            and blob.size[0] == blob.size[1]
            and blob.area == blob.size[0] ** 2
            and blob.color not in excluded_colors
        )
    ]


def _click(env, row, col):
    env.step(6, int(round(col)), int(round(row)))


def _move_square_one_step(env, square, target, step=None):
    row, col = square.centroid
    target_row, target_col = target
    if step is None:
        step = square.size[0] + 1
    _click(
        env,
        row + max(-step, min(step, target_row - row)),
        col + max(-step, min(step, target_col - col)),
    )


def _body_groups(env, color):
    frame = env.frame()
    remaining = {
        (row, col)
        for row in range(10, len(frame))
        for col in range(len(frame[0]))
        if int(frame[row][col]) == color
    }
    found = []
    while remaining:
        todo = [remaining.pop()]
        group = []
        while todo:
            row, col = todo.pop()
            group.append((row, col))
            near = {
                point for point in remaining
                if max(abs(point[0] - row), abs(point[1] - col)) <= 1
            }
            remaining -= near
            todo.extend(near)
        if len(group) >= 4:
            found.append(tuple(sorted(group)))
    return tuple(sorted(found))


def _body_center(points):
    return (
        round(sum(row for row, _ in points) / len(points)),
        round(sum(col for _, col in points) / len(points)),
    )


def _level_active(env, start_level):
    return not env.terminal() and env.levels_completed == start_level


def _control_body(env, start_level, color, offset, selector=None):
    if not _level_active(env, start_level):
        return False
    groups = _body_groups(env, color)
    if not groups:
        return False
    group = selector(groups) if selector is not None else groups[0]
    row, col = _body_center(group)
    point = (row + offset[0], col + offset[1])
    if point not in group:
        return False
    _click(env, *point)
    return True
def merge_equal_squares_around_moving_cutter(
    env, step=6, max_states=5000, max_depth=30, minimum_stage_mass=1
):
    """Plan collision-free equal-square merges, then deliver into the ring.

    ``minimum_stage_mass`` selects one merge cohort when smaller, unrelated
    squares share the playfield.
    """
    start_level = env.levels_completed
    stages = {
        color: mass
        for color, mass in ((10, 1), (6, 2), (15, 4), (11, 8))
        if mass >= minimum_stage_mass
    }

    def pieces(node):
        found = []
        for color, mass in stages.items():
            for blob in connected_components(
                node.frame(), colors=(color,), min_area=1
            ):
                if (
                    blob.bbox[0] >= 10
                    and blob.size[0] == blob.size[1]
                    and blob.area == blob.size[0] ** 2
                ):
                    found.append((color, mass, blob))
        return found

    def anchor(blob):
        r0, c0, r1, c1 = blob.bbox
        return (r0 + r1 + 1) // 2, (c0 + c1 + 1) // 2

    def avatar_centers(node):
        frame = node.frame()
        points = {
            (row, col)
            for row in range(10, len(frame))
            for col in range(len(frame[0]))
            if int(frame[row][col]) == 7
        }
        groups = []
        while points:
            todo = [points.pop()]
            group = []
            while todo:
                point = todo.pop()
                group.append(point)
                near = {
                    other for other in points
                    if max(
                        abs(point[0] - other[0]),
                        abs(point[1] - other[1]),
                    ) <= 1
                }
                points -= near
                todo.extend(near)
            groups.append(
                (
                    round(sum(row for row, _ in group) / len(group)),
                    round(sum(col for _, col in group) / len(group)),
                )
            )
        return tuple(sorted(groups))

    def rings(node):
        return [
            blob for blob in connected_components(
                node.frame(), colors=(9,), min_area=9
            )
            if blob.bbox[0] >= 10
        ]

    def state(node):
        movable = pieces(node)
        compact = tuple(
            sorted((color, blob.bbox) for color, _, blob in movable)
        )
        return movable, avatar_centers(node), compact

    def target_for(node, blob):
        targets = rings(node)
        if not targets:
            return None
        row, col = anchor(blob)
        return min(
            targets,
            key=lambda target: max(
                abs(row - round(target.centroid[0])),
                abs(col - round(target.centroid[1])),
            ),
        )

    def candidate_actions(node):
        movable, avatars, _ = state(node)
        proposed = []
        for color in stages:
            same = [
                blob for piece_color, _, blob in movable
                if piece_color == color
            ]
            pairs = []
            for index, left in enumerate(same):
                for right in same[index + 1:]:
                    lr, lc = anchor(left)
                    rr, rc = anchor(right)
                    distance = max(abs(lr - rr), abs(lc - rc))
                    pairs.append((distance, left, right))
            for distance, left, right in sorted(
                pairs, key=lambda item: item[0]
            )[:6]:
                for first, second in ((left, right), (right, left)):
                    fr, fc = anchor(first)
                    sr, sc = anchor(second)
                    if distance <= 2 * step:
                        row = round((fr + sr) / 2)
                        col = round((fc + sc) / 2)
                    else:
                        row = sr + max(-step, min(step, fr - sr))
                        col = sc + max(-step, min(step, fc - sc))
                    proposed.append((6, int(col), int(row)))

        for color, _, final in movable:
            if color != 11:
                continue
            target = target_for(node, final)
            if target is None:
                continue
            row, col = anchor(final)
            target_row = round(target.centroid[0])
            target_col = round(target.centroid[1])
            proposed.append(
                (
                    6,
                    int(col + max(-step, min(step, target_col - col))),
                    int(row + max(-step, min(step, target_row - row))),
                )
            )

        frame = node.frame()
        rows, cols = len(frame), len(frame[0])
        rows, cols = len(frame), len(frame[0])
        top, bottom = 13, rows - 5
        left, right = 4, cols - 5
        lower_left = left
        if any(
            max(
                abs(bottom - round(ring.centroid[0])),
                abs(left - round(ring.centroid[1])),
            ) <= 2 * step
            for ring in rings(node)
        ):
            lower_left += 2 * step
        proposed.extend(
            (6, col, row)
            for row, col in (
                (top, left),
                (top, right),
                (bottom, right),
                (bottom, lower_left),
            )
        )
        proposed.extend((6, col, row) for row, col in avatars)
        return list(dict.fromkeys(proposed))

    def priority(node, depth):
        movable, avatar, _ = state(node)
        if not movable:
            return 1_000_000
        merge_distance = 0
        for color in stages:
            same = [
                blob for piece_color, _, blob in movable
                if piece_color == color
            ]
            if len(same) >= 2:
                distances = []
                for index, left in enumerate(same):
                    for right in same[index + 1:]:
                        lr, lc = anchor(left)
                        rr, rc = anchor(right)
                        distances.append(max(abs(lr - rr), abs(lc - rc)))
                merge_distance += min(distances)

        clearance = min(
            (
                max(
                    abs(avatar_row - anchor(blob)[0]),
                    abs(avatar_col - anchor(blob)[1]),
                )
                for avatar_row, avatar_col in avatar
                for _, _, blob in movable
            ),
            default=0,
        )
        ring_distance = 0
        if len(movable) == 1 and movable[0][0] == 11:
            final = movable[0][2]
            target = target_for(node, final)
            if target is not None:
                row, col = anchor(final)
                ring_distance = max(
                    abs(row - round(target.centroid[0])),
                    abs(col - round(target.centroid[1])),
                )
        return (
            len(movable) * 100
            + merge_distance
            + ring_distance
            - min(clearance, 30)
            + depth
        )

    start = env.clone()
    initial, avatar, compact = state(start)
    initial_mass = sum(mass for _, mass, _ in initial)
    serial = itertools.count()
    heap = [(priority(start, 0), 0, next(serial), start, [])]
    seen = {(compact, avatar)}
    path = None
    expanded = 0
    while heap and expanded < max_states:
        _, depth, _, node, prefix = heapq.heappop(heap)
        expanded += 1
        if depth >= max_depth:
            continue
        for action in candidate_actions(node):
            child = node.clone()
            try:
                child.step(*action)
            except Exception:
                continue
            child_path = prefix + [action]
            if child.levels_completed > start_level:
                path = child_path
                heap = []
                break
            movable, child_avatar, child_compact = state(child)
            if (
                child.terminal()
                or sum(mass for _, mass, _ in movable) != initial_mass
            ):
                continue
            key = (child_compact, child_avatar)
            if key in seen:
                continue
            seen.add(key)
            heapq.heappush(
                heap,
                (
                    priority(child, len(child_path)),
                    len(child_path),
                    next(serial),
                    child,
                    child_path,
                ),
            )

    if path is None:
        return
    for action in path:
        if env.terminal() or env.levels_completed != start_level:
            return
        env.step(*action)

